MATCH (l:Location)<-[:OCCURRED_AT]-(c:Crime)
WHERE EXISTS {
  MATCH (:Person {name: "Lillian"})-[:KNOWS]->(:Person)-[:CURRENT_ADDRESS]->(l)
}
RETURN DISTINCT l.address

MATCH (c:Crime)-[:OCCURRED_AT]->(l:Location {address: "113 Blackburrn Street"})
WHERE c.last_outcome = "Completed investigation" AND NOT EXISTS { MATCH (:Person)-[:PARTY_TO]->(c) }
RETURN count(c)

MATCH (c:Crime)-[:OCCURRED_AT]->(:Location {address: "27 Lincoln Drive"})
WHERE EXISTS { MATCH (c)-[:INVESTIGATED_BY]->(:Officer) }
  AND NOT EXISTS { MATCH (:Person)-[:PARTY_TO]->(c) }
RETURN DISTINCT c.id

MATCH (johnsston_person:Person)-[:HAS_PHONE]->(johnsston_phone:Phone)
WHERE johnsston_person.surname = "Johnsston"
MATCH (other_person:Person)-[:HAS_PHONE]->(other_phone:Phone)
WHERE other_person.surname <> "Johnsston"
  AND (
    EXISTS {
      MATCH (pc:PhoneCall)-[:CALLER]->(other_phone)
      MATCH (pc)-[:CALLED]->(johnsston_phone)
    }
    OR EXISTS {
      MATCH (pc:PhoneCall)-[:CALLER]->(johnsston_phone)
      MATCH (pc)-[:CALLED]->(other_phone)
    }
  )
WITH DISTINCT other_phone
RETURN count(other_phone)
